        >
          <BubbleContent>{message.text}</BubbleContent>
          {hasReactions ? (
            <BubbleReactions side="bottom" align={mine ? "end" : "start"}>
              {message.reactions?.map((reaction) => (
                <span key={reaction} className="text-xs">
